from pathlib import Path
import re,json
c=Path(__file__).resolve().parent
metrics={}
for name in ['gameplay','overview','close','building','character']:
 metrics[name]={}
 for phase in ['before','after']:
  text=(c/phase/(name+'.metrics.txt')).read_text()
  metrics[name][phase]={k:float(v) for k,v in re.findall(r'(\w+)=([\d.]+)',text)}
(c/'performance.json').write_text(json.dumps(metrics,indent=2)+'\n')
