h=['<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Australian BBQ · Cartoon Backyard</title><style>'+style+'</style><main>', '<p>ACTUAL IMPLEMENTED CAPTURES · 20 OCTOBER 2026 · AWAITING REVIEW · VERIFIED 21 OCTOBER 2026</p><h1>A fresher Backyard, longer faces and one cheeky magpie</h1><p>A focused cartoon pass: warmer roof materials, clearer house trim, smoother clouds and gentler material highlights. Three low crates add cover in Backyard. The Face length slider, balloon handling and throw follow-through are ready to try.</p><p><a href="CHECKPOINT.md">Changes and recovery</a> · <a href="tests.log">642 tests passed</a> · <a href="build.log">Release build</a> · <a href="changed-files.json">Exact source files</a></p>']
for name,title,desc in [('gameplay','Gameplay view','Warm sunlight and ambient fill, softened material detail, new low cover. No new post-processing effects.'),('overview','Whole Backyard','Three additional crates appear only in Backyard. Shared rendering improvements also appear on reused scenery in the other modes.'),('close','Stacked-box detail','Existing climbable boxes and clothesline clearance remain. Wood keeps its painted texture, with the noisy normal mapping removed for the Pop style.'),('building','Sky and buildings','A warmer horizon, smoother cloud silhouettes, weatherboard and corrugated surfaces, window bars, sills and fascia detail.'),('character','Character and throw readability','Existing design and customisation retained. This fixed-camera view uses the controlled animation preview; it is rendered by the game.')]:
 h.append(f'<h2>{title}</h2><p>{desc} Left: before. Right: after.</p><div class="compare"><img src="before/{name}.png" alt="Before {title}"><img id="{name}" src="after/{name}.png" alt="After {title}"></div><label>Drag to compare<input aria-label="Compare {title}" type="range" min="0" max="100" value="50" oninput="document.getElementById(\'{name}\').style.clipPath=\'inset(0 0 0 \'+this.value+\'%)\'"></label>')
h.append('<h2>Face length</h2><p>0–100%, with 50% preserving the original head. Existing eyes and accessories follow the shape. Saved appearance and multiplayer replication are included. Direct clicking and dragging verified live updates at 0%, 50% and 100%; your original saved settings were preserved. These three captures use the same preview setup.</p><div class="grid trio">')
for name,label in [('short','0% · shorter'),('default','50% · original'),('long','100% · longer')]:h.append(f'<figure><img src="after/face-{name}.png" alt="{label}"><figcaption>{label}</figcaption></figure>')
