for name,label in [('balloon','Held balloon and release: smaller presentation, softer highlights, gentle sag and motion; existing trajectory and wet rules retained.'),('throw','Animation preview: weight-sensitive wind-up, release reach and a longer damped settle. Existing hit-stop, wobble and score feedback retained.'),('magpie','Backyard magpie: warning, committed swoop, one −10 peck, then retreat. This fixture holds a bot still to show contact; ordinary play allows dodging, catching or hitting the bird.')]:h.append(f'<figure><img src="{name}.webp" alt="{name} motion capture"><figcaption>{label}</figcaption></figure>')
h.append('<p>Magpie attacks are disabled in Teams, Heist, Smoko, Race and menu/results states. Team rescue mechanics are deferred. Attack state and penalties are host-authoritative.</p><h2>Performance</h2><table><tr><th>View</th><th>Before</th><th>After</th><th>Mean time change</th><th>p95 before → after</th></tr>')
for name,m in metrics.items():
 b,a=m['before'],m['after'];delta=(a['mean_ms']/b['mean_ms']-1)*100
